def generate(rng):
    # Background is 0.  A distractor field sits above a horizontal 2 divider;
    # below it is a rectangular 2-colour frame containing the payload.
    h2 = rng.randint(5, 18)
    w2 = rng.randint(5, 18)
    top_h = rng.randint(max(5, h2//2), max(6, h2*2))
    colors = [4, 6, 7, 9]
    def noisy(h,w):
        a = [[0 for _ in range(w)] for _ in range(h)]
        for r in range(h):
            for c in range(w):
                if rng.random() < .38:
                    a[r][c] = rng.choice(colors)
        return a
    g = noisy(top_h, w2+2)
    g.append([2]*(w2+2))
    for r in range(h2):
        g.append([2] + noisy(1,w2)[0] + [2])
    g.append([2]*(w2+2))
    return g"}

